// === Tab: mySketch ===
// This sketch uses as image from the artist 8machine _ on unsplash that is free to use. 
//It also uses a beat created on freesound by Cloud-10 called "EDM Sample 2"
let song;
var fft;

const MAX_TRAIL_COUNT = 30;
var colorScheme = ["#0A1B28", "#071F43", "#357D7E", "#35EEEE", "#919DF0"];
var trail = [];
var particles = [];
let color1;
let color2;
let colorArray = [];
let noiseScale = 0.01
var img;
let vibrations = [];

function preload() {
	song = loadSound('https://openprocessing.org/sketch/2096215/files/536163__cloud-10__edm-sample-2.mp3')
	img = loadImage('https://openprocessing.org/sketch/2096215/files/8machine.jpg')
}

function setup() {
	createMetaTag();
	createCanvas(window.innerWidth, window.innerHeight);
	const tone = [random(225, 255), random(225, 255), random(225, 255)]
	angleMode(DEGREES)
	imageMode(CENTER)
	rectMode(CENTER)
	fft = new p5.FFT(0.000003);

	img.filter(BLUR, 0.4);

	colorMode(HSB);
	//colors
}

class Particle {
	constructor() {
		this.pos = p5.Vector.random2D().mult(255)
		this.vel = createVector(0, 0)
		this.acc = this.pos.copy().mult(random(0.00001, 0.00001))

		this.w = random(1,( 0.3 * amp))
		//this.color = [random(200,220), random(45,315), random(45,90)]
		this.color = [random(200,400), random(0,150), 90, random(0.3, 1)]
		drawingContext.shadowBlur = 300
		drawingContext.shadowColor = (this.color);
		this.vel.mult(random(10));
		this.vel.rotate(radians(random(-25, 25)));
		this.mass = random(1, 50);
		this.airDrag = random(0.92, 0.98);
		this.life = 6;
		this.lifeSteps = random(-1, 1);
		this.pos.rotate(radians(this.life * 0.002));
		this.vel.mult(this.airDrag);
		this.pos.add(this.vel);
		this.life += this.lifeSteps;
	}
	 updateColor() {
    this.hue = (this.hue + 0.5) % 360
	 }
	 display() {
    noStroke();
    beginShape();
    for (let point of this.history) {
      fill(this.hue, 100, 100, 50);
      ellipse(point.x, point.y, this.radius * 2);
    }
    endShape();
	 }
	update(cond) {
		this.vel.add(this.acc)
		this.pos.add(this.vel)

		if (cond) {
			this.pos.add(noise *(this.vel) * 100)
			this.pos.add(noise *(this.vel) - 50)
			this.pos.add((this.vel) * 100)
			this.pos.add((this.vel) * 100)
			this.pos.add(this.vel)
			this.pos.add(this.vel)
			this.pos.add(this.vel)
			this.pos.add(this.vel)
			this.pos.add(this.vel)
			this.pos.add(this.vel)
			this.pos.add(noise *(this.vel) - 50)
			this.pos.add(noise *(this.vel) - 50)
			this.pos.add(noise *(this.vel) - 50)
		}
	}
	edges() {
		if(this.pos.x < -width / 2 || this.pos.x > width / 2 ||
		this.pos.y < -height / 2 || this.pos.y > height / 2) {
		return true
	} else {
		return false
		}
	}
	show() {
		noStroke()
		fill(this.color)
		ellipse(this.pos.x, this.pos.y,this.w);
	}
}

function draw() {
	background(0,1);
	noFill()
	colorMode (HSB)

	translate(width / 2, height / 2)

	fft.analyze()
	amp = fft.getEnergy(20, 255)

	push()
	if (amp > 230) {
		rotate(random(-4, 4))
	}

	image(img, 0, 0, width/2, height)
	pop()

	var alpha = map(amp, 0, 255, 180, 150)
	fill(0, alpha - 153)
	noStroke()
	rect(0, 0, width, height)

	var wave = fft.waveform();

	stroke(random(200,500), random(200,400), 100, 1)
	strokeWeight(random(3, 15))
	noFill()

for (var t = -1; t <= 1; t += 2) {	
	beginShape()
	for (var i = 0; i <= 180; i+= 0.7) { 
		var index = floor(map(i, 0, 180, 0, wave.length - 1))

		let r = map(wave[index], -1, 1, 150, 500)

		let x = r * sin(i) *t 
		let y = r * cos(i)
		//let x = 200 * cos(r) * sin(r);
		//let y = 200 * cos(r) * sin(r * 6);
		//vertex(x,y)
		//var x2 = x + (100 * noise( y / 50) - 50);
		//var y2 = y + (100 * noise(x / 50) - 50);
		vertex(x, y)
		}
	drawingContext.shadowBlur = 400
	drawingContext.shadowColor = (random(200,500), random(200,400), 100, 1);
		endShape()
	}
var p = new Particle()
particles.push(p)
vibrations.push(p)

	for (let i = particles.length - 1; i >= 0; i--) {
		if (!particles[i].edges()) {
			particles[i].update(amp > 230)
			particles[i].show()
	} else {
			particles.splice(i, 0.1)
			}
		}
}
function mouseClicked() {
	if (song.isPlaying()) {
		song.pause()
		noLoop()
	} else {
		song.play()
		loop()
	}
}
function windowResized() {
  resizeCanvas(window.innerWidth, window.innerHeight);
}

function createMetaTag() {
	let meta = createElement('meta');
	meta.attribute('name', 'viewport');
	meta.attribute('content', 'user-scalable=no,initial-scale=1,maximum-scale=1,minimum-scale=1,width=device-width,height=device-height');

	let head = select('head');
	meta.parent(head);
}

